  private set(panel: string, id: string, text: string) {
    const e = this.panels[panel];
    if (!e) return;
    setText(e, id, text);
  }

  updateHUD() {
    this.set('hud', 'score-val', `${this.game.score}`);
    this.set('hud', 'lives-val', `x${this.game.lives}`);
    this.set('hud', 'wave-val', `Wave ${this.game.wave}`);
    this.set('hud', 'high-val', `Best: ${this.game.highScore}`);
    if (this.game.mode === 'speed') {
      this.set('hud', 'timer-val', `${Math.ceil(this.game.speedTimer)}s`);
    } else {
      this.set('hud', 'timer-val', '');
    }
    if (this.game.currentCombo > 1) {
      const mul = this.game.comboMultiplier.toFixed(1);
      this.set('hud', 'combo-val', `x${this.game.currentCombo} (${mul}x)`);
    } else {
      this.set('hud', 'combo-val', '');
    }

    // Power-up indicator
    if (this.game.activePowerUp) {
      const names: Record<string, string> = { shield: 'SHIELD', rapid: 'RAPID', multi: 'MULTI' };
      const name = names[this.game.activePowerUp] || '';
      const secs = Math.ceil(this.game.powerUpTimer);
      this.set('hud', 'powerup-val', `${name} ${secs}s`);
    } else {
      this.set('hud', 'powerup-val', '');
    }

    // Boss HP indicator
    if (this.game.bossActive) {
      const filled = Math.ceil((this.game.bossHp / this.game.bossMaxHp) * 10);
      const bar = '|'.repeat(filled) + '.'.repeat(10 - filled);
      this.set('hud', 'boss-val', `BOSS [${bar}]`);
    } else {
      this.set('hud', 'boss-val', '');
    }
  }

  private updateMenu() {
    this.set('menu', 'high-score', `High Score: ${this.game.highScore}`);
    this.set('menu', 'mode-display', `Mode: ${this.game.mode.toUpperCase()}`);
  }

  private updateSettings() {
    this.set('settings', 'color-val', this.game.getColorName());
    this.set('settings', 'sound-val', this.game.soundEnabled ? 'ON' : 'OFF');
    this.set('settings', 'mode-val', this.game.mode.toUpperCase());
    this.set('settings', 'diff-val', this.game.difficulty.toUpperCase());
  }

  showResults() {
    const won = this.game.lives > 0;
    this.set('results', 'result-title', won ? 'VICTORY!' : 'GAME OVER');
    this.set('results', 'result-score', `Score: ${this.game.score}`);
    this.set('results', 'result-waves', `Waves: ${this.game.wavesCleared}`);
    this.set('results', 'result-accuracy', `Accuracy: ${this.game.getAccuracy()}%`);
    const stars = this.game.getStarRating();
    this.set('results', 'result-stars', '*'.repeat(stars) + '-'.repeat(3 - stars));
    this.set('results', 'result-time', `Time: ${Math.floor(this.game.gameTime)}s`);
    this.set('results', 'result-combo', `Best Combo: x${this.game.currentCombo > 0 ? this.game.currentCombo : 0}`);
    this.set('results', 'result-new-high', this.game.score >= this.game.highScore && this.game.score > 0 ? 'NEW HIGH SCORE!' : '');
    this.showHUD(false);
    this.showPanel('results');
  }

  private updateStats() {
    this.set('stats', 'stat-games', `Games Played: ${this.game.gamesPlayed}`);
    this.set('stats', 'stat-wins', `Games Won: ${this.game.totalGamesWon}`);
    this.set('stats', 'stat-high', `High Score: ${this.game.highScore}`);
    this.set('stats', 'stat-best-wave', `Best Wave: ${this.game.bestWave}`);
    this.set('stats', 'stat-kills', `Total Kills: ${this.game.totalKills}`);
    this.set('stats', 'stat-ufos', `UFOs Hit: ${this.game.totalUFOs}`);
    this.set('stats', 'stat-shots', `Total Shots: ${this.game.totalShots}`);
    this.set('stats', 'stat-accuracy', `Accuracy: ${this.game.totalShots > 0 ? Math.round(this.game.totalHits / this.game.totalShots * 100) : 0}%`);
    this.set('stats', 'stat-streak', `Best Streak: ${this.game.bestStreak}`);
    this.set('stats', 'stat-combo', `Best Combo: ${this.game.bestCombo}`);
    this.set('stats', 'stat-bosses', `Bosses Killed: ${this.game.totalBossKills}`);
    this.set('stats', 'stat-powerups', `Power-Ups: ${this.game.totalPowerUpsEver}`);
  }

  private updateAch() {
    const all = [
      'First Blood', 'Wave Rider', 'Sharpshooter', 'UFO Hunter',
      'Combo x5', 'Combo x10', 'Wave 5', 'Wave 10',
      'Score 1000', 'Score 5000', 'Score 10000', 'Perfect Wave',
      'UFO Master', 'Survivor', 'Speed Demon', 'Challenge Clear',
      'Marathon', '10 Games', 'Win Streak 3', 'Untouchable',
      'Power Up!', 'Power Hoarder', 'Bomb Expert', 'Boss Slayer', 'Boss Hunter',
      'Combo x15', 'Multiplier Max', 'Wave 15', 'Score 25000', 'Collector',
    ];
    const totalPages = Math.ceil(all.length / 10);
    const perPage = 10;
    const start = this.achPage * perPage;
    const page = all.slice(start, start + perPage);
    for (let i = 0; i < perPage; i++) {
      const ach = page[i];
      const unlocked = ach ? this.game.achievements.includes(ach) : false;
      this.set('achpanel', `ach-${i}`, ach ? (unlocked ? `[*] ${ach}` : `[ ] ${ach}`) : '');
    }
    this.set('achpanel', 'ach-page', `${this.achPage + 1}/${totalPages}`);
    this.set('achpanel', 'ach-count', `${this.game.achievements.length}/${all.length}`);
  }

  private updateLeaderboard() {
    const lb = this.game.leaderboard;
    for (let i = 0; i < 5; i++) {
      if (i < lb.length) {
        const entry = lb[i];
        this.set('leaderboard', `score-${i}`, `${entry.score}`);
        this.set('leaderboard', `info-${i}`, `W${entry.wave} ${entry.mode.toUpperCase()} ${entry.date}`);
      } else {
        this.set('leaderboard', `score-${i}`, '---');
        this.set('leaderboard', `info-${i}`, '');
      }
    }
  }

  showAchievement(name: string) {
    this.set('hud', 'ach-notify', `Achievement: ${name}!`);
    this.notifyTimer = 3;
    this.audio?.playSound('achievement');
  }

  showPowerUpNotify(type: string) {
    const names: Record<string, string> = {
      shield: 'SHIELD ACTIVE!',
      rapid: 'RAPID FIRE!',
      multi: 'MULTI-SHOT!',
      bomb: 'BOMB!',
    };
    this.set('hud', 'ach-notify', names[type] || 'POWER-UP!');
    this.powerUpNotifyTimer = 2;
  }

  showWaveTransition(wave: number) {
    const theme = this.game.getWaveThemeName();
    this.set('hud', 'wave-announce', `WAVE ${wave}`);
    this.set('hud', 'wave-theme', `${theme} Zone`);
    this.waveTransitionTimer = 1.5;
    this.audio?.playSound('waveTransition');
  }

  update(delta: number) {
    if (this.notifyTimer > 0) {
      this.notifyTimer -= delta;
      if (this.notifyTimer <= 0) {
        this.set('hud', 'ach-notify', '');
      }
    }
    if (this.powerUpNotifyTimer > 0) {
      this.powerUpNotifyTimer -= delta;
      if (this.powerUpNotifyTimer <= 0 && this.notifyTimer <= 0) {
        this.set('hud', 'ach-notify', '');
      }
    }
    if (this.waveTransitionTimer > 0) {
      this.waveTransitionTimer -= delta;
      if (this.waveTransitionTimer <= 0) {
        this.set('hud', 'wave-announce', '');
        this.set('hud', 'wave-theme', '');
      }
    }
    if (this.game.state === 'results' && this.activePanel === 'hud') {
      this.showResults();
    }
  }
}

import { createSystem } from '@iwsdk/core';

export class AudioSystem extends createSystem({}) {
  private ctx: AudioContext | null = null;
  private enabled = true;
  private pitchIdx = 0;
  private readonly pitchVariants = [1.0, 1.05, 0.95, 1.02];

  init() {
    try { this.ctx = new AudioContext(); } catch { /* no audio */ }
  }

  setEnabled(e: boolean) { this.enabled = e; }

  playSound(name: string) {
    if (!this.ctx || !this.enabled) return;
    if (this.ctx.state === 'suspended') this.ctx.resume();

    const pitch = this.pitchVariants[this.pitchIdx % this.pitchVariants.length];
    this.pitchIdx++;

    switch (name) {
      case 'shoot': this.tone(880 * pitch, 0.06, 'square', 0.15); break;
      case 'hit': this.tone(440 * pitch, 0.1, 'square', 0.2); this.tone(660 * pitch, 0.08, 'sine', 0.12, 0.05); break;
      case 'playerHit': this.noise(0.2, 0.25); this.tone(200, 0.3, 'sawtooth', 0.15); break;
      case 'enemyShoot': this.tone(300 * pitch, 0.08, 'sawtooth', 0.08); break;
      case 'step': this.tone(120 * pitch, 0.04, 'square', 0.04); break;
      case 'drop': this.tone(80, 0.15, 'sawtooth', 0.1); this.tone(60, 0.2, 'square', 0.08, 0.1); break;
      case 'ufo': this.tone(600, 0.3, 'sine', 0.1); this.tone(620, 0.3, 'sine', 0.08, 0.1); this.tone(580, 0.3, 'sine', 0.06, 0.2); break;
      case 'ufoHit': this.tone(1200, 0.15, 'square', 0.2); this.tone(800, 0.15, 'square', 0.15, 0.1); break;
      case 'waveClear': this.playMelody([523, 659, 784, 1047], 0.12, 'sine', 0.15); break;
      case 'victory': this.playMelody([523, 659, 784, 1047, 1319], 0.15, 'sine', 0.2); break;
      case 'defeat': this.playMelody([440, 392, 349, 330], 0.2, 'sine', 0.15); break;
      case 'click': this.tone(1000 * pitch, 0.03, 'square', 0.1); break;
      case 'start': this.playMelody([262, 330, 392, 523], 0.1, 'square', 0.15); break;
      case 'achievement': this.playMelody([784, 988, 1175], 0.1, 'sine', 0.2); break;
      // New power-up sounds
      case 'powerup': this.playMelody([660, 880, 1100], 0.08, 'sine', 0.2); this.tone(440, 0.15, 'triangle', 0.1, 0.2); break;
      case 'bomb': this.noise(0.4, 0.35); this.tone(100, 0.5, 'sawtooth', 0.2); this.tone(60, 0.6, 'sawtooth', 0.15, 0.2); break;
      case 'shieldBlock': this.tone(1200 * pitch, 0.08, 'sine', 0.15); this.tone(900, 0.12, 'sine', 0.1, 0.05); break;
      // Boss sounds
      case 'bossAppear': this.noise(0.15, 0.1); this.playMelody([200, 250, 300, 350], 0.15, 'sawtooth', 0.2); break;
      case 'bossShoot': this.tone(200 * pitch, 0.12, 'sawtooth', 0.12); this.tone(150, 0.15, 'square', 0.08, 0.05); break;
      case 'bossDefeat': this.noise(0.5, 0.3); this.playMelody([400, 500, 600, 800, 1000], 0.12, 'square', 0.2); break;
      // Wave transition
      case 'waveTransition': this.playMelody([392, 523, 659], 0.1, 'triangle', 0.18); break;
      // Combo sounds
      case 'comboUp': this.tone(1200 * pitch, 0.05, 'sine', 0.12); this.tone(1600 * pitch, 0.04, 'sine', 0.1, 0.03); break;
    }
  }

  private tone(freq: number, dur: number, type: OscillatorType, vol: number, delay = 0) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    gain.gain.setValueAtTime(vol, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc.connect(gain).connect(this.ctx.destination);
    osc.start(t);
    osc.stop(t + dur + 0.01);
  }

  private noise(dur: number, vol: number) {
    if (!this.ctx) return;
    const bufferSize = this.ctx.sampleRate * dur;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * vol;
    }
    const source = this.ctx.createBufferSource();
    source.buffer = buffer;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(vol, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + dur);
    source.connect(gain).connect(this.ctx.destination);
    source.start();
  }

  private playMelody(notes: number[], noteDur: number, type: OscillatorType, vol: number) {
    for (let i = 0; i < notes.length; i++) {
      this.tone(notes[i], noteDur, type, vol, i * noteDur * 0.9);
    }
  }
}

import { World, PanelUI, Group } from '@iwsdk/core';
import { GameSystem } from './game-system';
import { UISystem } from './ui-system';
import { AudioSystem } from './audio-system';
import { EffectsSystem } from './effects-system';
import { EnvironmentSystem } from './environment-system';

const container = document.getElementById('scene-container') as HTMLDivElement;

const world = await World.create(container, {
  xr: { offer: 'once' },
  input: { canvasPointerEvents: true },
  features: {
    locomotion: { browserControls: true },
  },
  render: {
    near: 0.01,
    far: 200,
    defaultLighting: false,
    camera: { position: [0, 1.6, 5], lookAt: [0, 1.5, 0] },
  },
});

// === Panel Entities ===
const pY = 1.5, pZ = 3.5;
const panelDefs: { key: string; config: string; pos: [number, number, number]; show: boolean }[] = [
  { key: 'menu',        config: './ui/menu.json',         pos: [0, pY, pZ],      show: true },
  { key: 'hud',         config: './ui/hud.json',          pos: [0, 2.3, 3.8],    show: false },
  { key: 'pause',       config: './ui/pause.json',        pos: [0, pY, pZ],      show: false },
  { key: 'results',     config: './ui/results.json',      pos: [0, pY, pZ],      show: false },
  { key: 'achpanel',    config: './ui/achpanel.json',     pos: [0, pY, pZ],      show: false },
  { key: 'settings',    config: './ui/settings.json',     pos: [0, pY, pZ],      show: false },
  { key: 'stats',       config: './ui/stats.json',        pos: [0, pY, pZ],      show: false },
  { key: 'tutorial',    config: './ui/tutorial.json',     pos: [0, pY, pZ],      show: false },
  { key: 'leaderboard', config: './ui/leaderboard.json',  pos: [0, pY, pZ],      show: false },
];

const panelEntities: Record<string, any> = {};
const panelPositions: Record<string, [number, number, number]> = {};

for (const pd of panelDefs) {
  const grp = new Group();
  grp.position.set(pd.pos[0], pd.show ? pd.pos[1] : -50, pd.pos[2]);
  grp.scale.set(1.4, 1.4, 1.4);
  const entity = world.createTransformEntity(grp);
  entity.addComponent(PanelUI, { config: pd.config });
  panelEntities[pd.key] = entity;
  panelPositions[pd.key] = pd.pos;
}

world
  .registerSystem(EnvironmentSystem)
  .registerSystem(AudioSystem)
  .registerSystem(EffectsSystem)
  .registerSystem(GameSystem)
  .registerSystem(UISystem);

const game = world.getSystem(GameSystem)!;
const ui = world.getSystem(UISystem)!;
const audio = world.getSystem(AudioSystem)!;
const effects = world.getSystem(EffectsSystem)!;
const env = world.getSystem(EnvironmentSystem)!;

game.setRefs({ ui, audio, effects, env });
ui.setRefs({ game, audio, panels: panelEntities, positions: panelPositions });

